class Solution:
    def maximumPrimeDifference(self, nums: List[int]) -> int:
        def is_prime(n):
            if n < 2:
                return False
            if n == 2:
                return True
            if n % 2 == 0:
                return False
            # Check odd divisors up to sqrt(n)
            i = 3
            while i * i <= n:
                if n % i == 0:
                    return False
                i += 2
            return True

        # Find the first and last index where prime numbers occur
        first_prime_idx = -1
        last_prime_idx = -1

        for i, num in enumerate(nums):
            if is_prime(num):
                if first_prime_idx == -1:
                    first_prime_idx = i
                last_prime_idx = i

        # The maximum distance is between the first and last prime indices
        return last_prime_idx - first_prime_idx

